#include <bits/stdc++.h>
using namespace std;

int main() {
    int a[8][8], ans = 16;
    string g;

    for (int i = 0; i < 8; ++i) {
        cin >> g;
        for (int j = 0; j < 8; ++j)
            a[i][j] = (g[j] == 'B');
    }

    for (int row = 0; row < (1 << 8); ++row) {
        for (int col = 0; col < (1 << 8); ++col) {
            bool valid = true;
            for (int i = 0; i < 8 && valid; ++i) {
                for (int j = 0; j < 8; ++j) {
                    if ((((row >> i) & 1) || ((col >> j) & 1)) != a[i][j]) {
                        valid = false;
                        break;
                    }
                }
            }
            if (valid)
                ans = min(ans, __builtin_popcount(row) + __builtin_popcount(col));
        }
    }

    cout << ans;
    return 0;
}

